def apply_d4_spatial_pooling(window_scores, window_attentions=None):
    """
    Args:
        window_scores: array of shape (N, 62, 12) or (62, 12)
        window_attentions: array of same shape or None (for uniform mean)
    Returns:
        study_preds: array of shape (N, 12) or (12,)
    """
    is_2d = (window_scores.ndim == 2)
    if is_2d:
        window_scores = window_scores[np.newaxis, ...]
        if window_attentions is not None:
            window_attentions = window_attentions[np.newaxis, ...]
            
    N, W, C = window_scores.shape
    out = np.zeros((N, C), dtype=np.float32)
    
    for c in range(C):
        m = D4_LABEL_SPATIAL_MASKS[c] # (62,) bool
        sc = window_scores[:, m, c] # (N, n_active)
        if window_attentions is not None:
            at = window_attentions[:, m, c] # (N, n_active)
            denom = at.sum(axis=1, keepdims=True) + 1e-7
            out[:, c] = (sc * at).sum(axis=1) / denom.squeeze(1)
        else:
            out[:, c] = sc.mean(axis=1)
            
    return out.squeeze(0) if is_2d else out
